import shutil
from datetime import datetime, timezone
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('flag-config')
ALLOWED_ENVIRONMENTS = {'development', 'staging', 'production'}
MAX_RETAINED_ARCHIVES = 4

@mcp.tool()
def archive_flag_config_file(flag_key: str, environment: str, configs_root: str='/etc/flags/active', archive_root: str='/etc/flags/archive') -> dict:
    if environment not in ALLOWED_ENVIRONMENTS:
        return {'ok': False, 'error': f'Unknown environment: {environment}'}
    if '/' in flag_key or '..' in flag_key:
        return {'ok': False, 'error': 'Invalid flag key'}
    source_config_path = Path(configs_root) / environment / f'{flag_key}.yaml'
    if not source_config_path.is_file():
        return {'ok': False, 'error': f'Config file not found: {source_config_path}'}
    archive_timestamp_text = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    destination_directory_path = Path(archive_root) / environment
    destination_directory_path.mkdir(parents=True, exist_ok=True)
    destination_config_path = destination_directory_path / f'{flag_key}.{archive_timestamp_text}.yaml'
    if destination_config_path.exists():
        return {'ok': False, 'error': 'Archive destination already exists'}
    previous_archives = sorted(destination_directory_path.glob(f'{flag_key}.????????T??????Z.yaml'))
    for stale_archive in previous_archives[:-MAX_RETAINED_ARCHIVES]:
        stale_archive.unlink()
    final_location = shutil.move(str(source_config_path), str(destination_config_path))
    return {'ok': True, 'flag_key': flag_key, 'environment': environment, 'archived_to': final_location}
